// ELEMENTS:
// 1. Navy com o filete vermelho no topo
// 2. Casa montada por blocos de cor: paredes azul royal sobem, telhado vermelho cai, porta e janelas
// 3. Pergunta (anim.text, **palavras** em Heavy) palavra a palavra
// 4. Quatro cartões coloridos numerados (cards) a abrir em leque a partir de cardsAt (s)
// 5. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const BLUE = "#013BA9";
const TINT = "#E8EEF9";
const RED = "#DE212B";
const WHITE = "#FFFFFF";
const MIST = "#C9D3E3";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.6));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.28) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.07, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const words = (text: string): { w: string; bold: boolean }[] => {
  const out: { w: string; bold: boolean }[] = [];
  text.split(/(\*\*[^*]+\*\*)/).forEach((part) => {
    const bold = part.startsWith("**");
    part.replace(/\*\*/g, "").split(/\s+/).filter(Boolean).forEach((w) => {
      if (out.length && !/[\p{L}\p{N}]/u.test(w)) out[out.length - 1].w += w;
      else out.push({ w, bold });
    });
  });
  return out;
};

const CARD_COLORS = [
  { bg: BLUE, fg: WHITE },
  { bg: WHITE, fg: NAVY },
  { bg: RED, fg: WHITE },
  { bg: TINT, fg: NAVY },
];

const AberturaBlocos: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const u = format === "landscape" ? box.height / 1080 : format === "half" ? (box.height / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const cards = Array.isArray(p.cards) ? (p.cards as unknown[]).map(String).slice(0, 4) : [];
  const cardsAt = Number(p.cardsAt ?? 2) || 2;
  const list = words(String(anim.text ?? ""));

  const t = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const walls = t(0.05, 0.55, BACK);
  const roof = t(0.4, 0.6, Easing.out(Easing.bounce));
  const door = t(0.8, 0.4, BACK);
  const win = t(0.95, 0.4, BACK);
  const S = 300 * u;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", flexDirection: "column", gap: 46 * u, padding: `0 ${80 * u}px` }}>
        <svg width={S} height={S} viewBox="0 0 120 120" style={{ overflow: "visible" }}>
          <ellipse cx={60} cy={110} rx={50 * walls} ry={4} fill="rgba(0,0,0,0.35)" />
          <g transform={`translate(0 ${110 * (1 - walls)}) translate(60 110) scale(1 ${walls}) translate(-60 -110)`}>
            <rect x={22} y={52} width={76} height={58} rx={3} fill={BLUE} />
          </g>
          <g transform={`translate(0 ${-90 * (1 - roof)})`} opacity={roof > 0 ? 1 : 0}>
            <path d="M12 56 L60 16 L108 56 Z" fill={RED} strokeLinejoin="round" stroke={RED} strokeWidth={4} />
            <rect x={80} y={24} width={10} height={20} fill={RED} />
          </g>
          <rect x={52} y={110 - 34 * door} width={16} height={34 * door} rx={2} fill={WHITE} />
          {[[32, 66], [76, 66]].map(([x, y], i) => (
            <rect key={i} x={x + 6 - 6 * win} y={y + 6 - 6 * win} width={12 * win} height={12 * win} rx={1.5} fill={TINT} />
          ))}
        </svg>
        <div style={{ display: "flex", flexWrap: "wrap", justifyContent: "center", columnGap: 26 * u, maxWidth: 920 * u }}>
          {list.map((x, i) => {
            const k = t(0.9 + i * 0.1, 0.6);
            return (
              <span key={i} style={{ fontFamily: FONTS.display, fontWeight: x.bold ? 800 : 300, fontSize: 116 * u, lineHeight: 1.05, color: WHITE, display: "inline-block", opacity: k, transform: `translateY(${(1 - k) * 40 * u}px)` }}>{x.w}</span>
            );
          })}
        </div>
        <div style={{ width: t(cardsAt - 0.3, 0.6) * 120 * u, height: 3 * u, background: RED }} />
        <div style={{ display: "grid", gridTemplateColumns: "repeat(2, minmax(0, 1fr))", gap: 22 * u, width: 900 * u }}>
          {cards.map((c, i) => {
            const k = t(cardsAt + i * 0.14, 0.55, BACK);
            const col = CARD_COLORS[i % 4];
            return (
              <div key={i} style={{ background: col.bg, color: col.fg, borderRadius: 22 * u, padding: `${26 * u}px ${30 * u}px`, display: "flex", alignItems: "center", gap: 22 * u, opacity: Math.min(1, k * 1.5), transform: `translateY(${(1 - k) * 60 * u}px) rotate(${(1 - k) * (i % 2 ? 6 : -6)}deg)`, boxShadow: "0 18px 40px rgba(0,0,0,0.28)" }}>
                <div style={{ fontFamily: FONTS.display, fontWeight: 800, fontSize: 64 * u, lineHeight: 1 }}>{i + 1}</div>
                <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 30 * u, lineHeight: 1.15 }}>{c}</div>
              </div>
            );
          })}
        </div>
        <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 26 * u, letterSpacing: "0.32em", textTransform: "uppercase", color: MIST, opacity: t(cardsAt + 0.7, 0.5) }}>{String(p.sub ?? "")}</div>
      </AbsoluteFill>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: RED }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default AberturaBlocos;
